# -*- coding: utf-8 -*-
# IK_ODA_ORG_V1 — Ik Odasi organizma: /api/bi/ik/oda zengin veri ucu + shells/ik.html yeni kabuk.
# Idempotent, .ikorgbak yedekli. Server handler start/end anchor ile guvenli degistirilir.
import io, os, sys, base64
BASE = sys.argv[1] if len(sys.argv) > 1 else "."
SRV = os.path.join(BASE, "server_container.mjs")
CLI = os.path.join(BASE, "shells", "ik.html")
MARK = "IK_ODA_ORG_V2"
HANDLER = base64.b64decode("").decode("utf-8")
HTML = base64.b64decode("").decode("utf-8")
srv = io.open(SRV, encoding="utf-8").read()
if MARK in srv:
    print("SKIP server (zaten var)")
else:
    START = '  if (request.method === "GET" && url.pathname === "/api/bi/ik/oda") {'
    END = '  if (request.method === "GET" && url.pathname === "/api/bi/finans-odasi") {'
    assert srv.count(START) == 1, "START=%d" % srv.count(START)
    assert END in srv, "END anchor yok"
    si = srv.index(START)
    ei = srv.index(END, si)
    assert ei > si, "sira hatasi"
    srv2 = srv[:si] + HANDLER + "\n\n" + srv[ei:]
    if not os.path.exists(SRV + ".ikorgbak"):
        io.open(SRV + ".ikorgbak", "w", encoding="utf-8").write(srv)
    io.open(SRV, "w", encoding="utf-8").write(srv2)
    print("OK server | MARK:", srv2.count(MARK))
if os.path.exists(CLI) and not os.path.exists(CLI + ".ikorgbak"):
    io.open(CLI + ".ikorgbak", "w", encoding="utf-8").write(io.open(CLI, encoding="utf-8").read())
io.open(CLI, "w", encoding="utf-8").write(HTML)
print("OK client | shells/ik.html yazildi (", len(HTML), "byte)")
